import{_ as a,o as t,c as o,ae as r}from"./chunks/framework.BD9pLfSD.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"面试/08.deno相关问题.md","filePath":"面试/08.deno相关问题.md","lastUpdated":1769081193000}'),n={name:"面试/08.deno相关问题.md"};function s(i,e,l,d,p,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h3 id="deno发公告说要把部分ts代码重构为js。-你觉得这是什么原因-【开放性讨论】" tabindex="-1">Deno发公告说要把部分ts代码重构为js。 你觉得这是什么原因？【开放性讨论】 <a class="header-anchor" href="#deno发公告说要把部分ts代码重构为js。-你觉得这是什么原因-【开放性讨论】" aria-label="Permalink to &quot;Deno发公告说要把部分ts代码重构为js。 你觉得这是什么原因？【开放性讨论】&quot;">​</a></h3><h2 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h2><ol><li>node是把包下载到本地，deno是直接引用远程地址</li><li>编译时间太长，所以放弃了 ts</li><li>还有一些场景不太适合 ts：经常修改原型链的，需要运行时动态添加属性的。</li></ol><h2 id="官方回答" tabindex="-1">官方回答 <a class="header-anchor" href="#官方回答" aria-label="Permalink to &quot;官方回答&quot;">​</a></h2><p>在使用 TypeScript 编写内部代码时，Deno 团队遇到了以下几个现实问题： 在变更文件时，TypeScript 往往需要几分钟的编译时间，这就导致连续编译过程变得非常缓慢； 在创建 Deno 可执行文件以及面向用户的 API 源文件时，TypeScript 结构会引发一系列运行时性能问题； TypeScript 本身对于 Deno 代码的组织工作毫无帮助，反而增强了代码组织负担。Deno 团队提出的一大现实问题，是 TypeScript 会在两个位置复制相互独立的 Body 类； <a href="https://github.com/denoland/deno/issues/4748" target="_blank" rel="noreferrer">https://github.com/denoland/deno/issues/4748</a> 由于 TypeScript 编译器无法帮助开发者生成 d.ts 文件，内部代码与运行时 TypeScript 声明必须以手动方式保持同步； 他们维护着两台 TS 编译器主机：一台用于内部 Deno 代码，另一台用于外部用户代码，但二者的作用其实非常相似。</p><h2 id="扩展链接" tabindex="-1">扩展链接 <a class="header-anchor" href="#扩展链接" aria-label="Permalink to &quot;扩展链接&quot;">​</a></h2><ol><li><a href="https://mp.weixin.qq.com/s/h1ZNewMZZC20o80P37KqsQ" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/h1ZNewMZZC20o80P37KqsQ</a></li></ol>',7)])])}const m=a(n,[["render",s]]);export{_ as __pageData,m as default};
